entries.script:
pm.test('signup accepts a submission with only email and password, per the canonical spec (KNOWN DRIFT: the live API also requires username and country - see postman/README.md)', function () {
  pm.expect(pm.response.code, 'expected HTTP 200 for a spec-minimal submission').to.equal(200);
});

pm.test('signup rejects a submission with no email and names the email field', function () {
  pm.expect(pm.response.code).to.equal(400);
  const body = pm.response.json();
  pm.expect(body, 'response should name the offending field').to.have.property('email');
});

pm.test('signup rejects a submission with no password and names the password field', function () {
  pm.expect(pm.response.code).to.equal(400);
  const body = pm.response.json();
  pm.expect(body).to.have.property('password');
});

pm.test('signup rejects a malformed email and names the email field', function () {
  pm.expect(pm.response.code).to.equal(400);
  const body = pm.response.json();
  pm.expect(body).to.have.property('email');
});

pm.test('signup rejects a second submission for an email that already has an account', function () {
  pm.expect(pm.response.code).to.equal(400);
  const body = pm.response.json();
  pm.expect(body, 'response should name the email field').to.have.property('email');
});

pm.test('signup rejects a password shorter than 8 characters and names the password field', function () {
  pm.expect(pm.response.code).to.equal(400);
  const body = pm.response.json();
  pm.expect(body).to.have.property('password');
});

pm.test('signup rejects a password with no digit and names the password field', function () {
  pm.expect(pm.response.code).to.equal(400);
  const body = pm.response.json();
  pm.expect(body).to.have.property('password');
});

pm.test('a valid submission creates an account (verified indirectly: the same email is then rejected as a duplicate by a later request in this run)', function () {
  pm.expect(pm.response.code, 'expected the account to be created').to.equal(200);
});

pm.test('a successful signup response never contains the submitted password', function () {
  pm.expect(pm.response.text()).to.not.include('Passw0rd1');
});

pm.test('a rejected signup names at least one offending field', function () {
  pm.expect(pm.response.code, 'expected the missing-email submission to be rejected').to.equal(400);
  const body = pm.response.json();
  pm.expect(Object.keys(body).length, 'expected at least one field named in the error body').to.be.above(0);
});

pm.test('a successful signup returns HTTP 200 with a body containing only the email field (KNOWN DRIFT: the live API also returns username - see postman/README.md)', function () {
  pm.expect(pm.response.code).to.equal(200);
  const body = pm.response.json();
  pm.expect(Object.keys(body), 'response body should contain only \'email\'').to.eql(['email']);
});

pm.test('the stored/returned email is lowercase even when submitted with mixed case', function () {
  const body = pm.response.json();
  const expectedLower = pm.collectionVariables.get('signupEmailLower');
  pm.expect(body.email).to.eql(expectedLower);
});

pm.test('a second signup for the same email in different casing is rejected as a duplicate', function () {
  pm.expect(pm.response.code, 'expected the case-differing duplicate to be rejected').to.equal(400);
});
